import { ALLOWLIST, USER_AGENT, VERSION, isAllowed } from './allowlist.js';

/**
 * Request handler for the Zurich maps Workers site.
 *
 * The Worker only answers `/api/*` (see `assets.run_worker_first` in
 * wrangler.jsonc); every other request is served directly from the static asset
 * directory `public/`.
 *
 * Why a proxy at all?
 *  - swisstopo SearchServer (`api3.geo.admin.ch`) sends CORS `*`, but routing it
 *    through the Worker gives us one stable origin, a bounded query and an edge
 *    cache in front of a public service we want to call politely.
 *  - e-rara IIIF images/manifests normally allow CORS; `/api/fetch` is a
 *    *fallback* for clients/networks where the direct call fails. It is limited
 *    to a literal allowlist of hosts, so it cannot be used as an open proxy.
 *
 * No credentials are required or read by this Worker.
 */

function json(body, init = {}) {
  return new Response(JSON.stringify(body, null, 1), {
    ...init,
    headers: { 'content-type': 'application/json; charset=utf-8', ...(init.headers || {}) },
  });
}

async function upstream(url, { accept = '*/*', timeoutMs = 8000 } = {}) {
  return fetch(url, {
    headers: { 'user-agent': USER_AGENT, accept },
    signal: AbortSignal.timeout(timeoutMs),
    redirect: 'follow',
  });
}

/** Read a JSON file that ships with the site through the assets binding. */
async function asset(env, path, request) {
  const url = new URL(request.url);
  url.pathname = path;
  url.search = '';
  return env.ASSETS.fetch(new Request(url.toString(), { method: 'GET' }));
}

async function cachedJson(request, ctx, build, maxAge) {
  const cache = caches.default;
  const cacheKey = new Request(new URL(request.url).toString(), { method: 'GET' });
  const hit = await cache.match(cacheKey);
  if (hit) return hit;
  const body = await build();
  const res = json(body, { headers: { 'cache-control': `public, max-age=${maxAge}` } });
  ctx.waitUntil(cache.put(cacheKey, res.clone()));
  return res;
}

/** GET /api/health — liveness plus the upstreams this Worker may contact. */
function health(request) {
  return json({
    ok: true,
    version: VERSION,
    runtime: 'cloudflare-workers',
    upstreams: ALLOWLIST.map((r) => r.host),
    endpoints: ['/api/health', '/api/records', '/api/layers', '/api/sources', '/api/search/places', '/api/fetch'],
    time: new Date().toISOString(),
  });
}

/** GET /api/search/places?q=&limit= — swisstopo SearchServer (type=locations). */
async function searchPlaces(request, ctx) {
  const url = new URL(request.url);
  const q = (url.searchParams.get('q') || '').trim();
  const limit = Math.min(Math.max(Number(url.searchParams.get('limit') || 8), 1), 20);
  if (q.length < 2 || q.length > 120) {
    return json({ error: 'query_too_short', detail: 'q must be 2..120 characters', results: [] }, { status: 400 });
  }
  return cachedJson(
    request,
    ctx,
    async () => {
      const target = new URL('https://api3.geo.admin.ch/rest/services/api/SearchServer');
      target.searchParams.set('searchText', q);
      target.searchParams.set('type', 'locations');
      target.searchParams.set('sr', '4326'); // WGS84 lon/lat
      target.searchParams.set('limit', String(limit));
      const res = await upstream(target.toString(), { accept: 'application/json' });
      if (!res.ok) {
        return { results: [], upstreamStatus: res.status, note: 'swisstopo SearchServer error' };
      }
      const data = await res.json();
      const results = (data.results || []).map((r) => {
        const a = r.attrs || {};
        const box = (a.geom_st_box2d || 'BOX(0 0,0 0)').match(/BOX\(([-\d.]+) ([-\d.]+),([-\d.]+) ([-\d.]+)\)/);
        return {
          label: String(a.label || '').replace(/<[^>]*>/g, ''),
          origin: a.origin || null,
          lat: typeof a.lat === 'number' ? a.lat : null,
          lon: typeof a.lon === 'number' ? a.lon : null,
          layerBodId: a.layerBodId || null,
          // upstream `zoomlevel` is a bitfield/uint32 for some origins; only pass sane values on
          zoom: Number.isFinite(a.zoomlevel) && a.zoomlevel > 0 && a.zoomlevel <= 20 ? a.zoomlevel : null,
          bbox: box ? { west: Number(box[1]), south: Number(box[2]), east: Number(box[3]), north: Number(box[4]) } : null,
        };
      });
      return { results, source: 'swisstopo SearchServer', attribution: '© swisstopo' };
    },
    300,
  );
}

/** GET /api/fetch?url= — allowlisted pass-through with a 1 h edge cache. */
async function fetchUpstream(request, ctx) {
  const url = new URL(request.url);
  const raw = url.searchParams.get('url');
  if (!raw) return json({ error: 'missing_url' }, { status: 400 });
  let target;
  try {
    target = new URL(raw);
  } catch {
    return json({ error: 'invalid_url' }, { status: 400 });
  }
  if (!isAllowed(target)) {
    return json({ error: 'host_not_allowed', host: target.hostname, allowlist: ALLOWLIST.map((r) => r.host) }, { status: 403 });
  }
  const cache = caches.default;
  const cacheKey = new Request(`${url.origin}/api/fetch?url=${encodeURIComponent(target.toString())}`, { method: 'GET' });
  const hit = await cache.match(cacheKey);
  if (hit) return hit;
  let res;
  try {
    res = await upstream(target.toString(), { accept: url.searchParams.get('accept') || '*/*' });
  } catch (err) {
    return json({ error: 'upstream_unreachable', detail: String(err && err.message) }, { status: 502 });
  }
  if (!res.ok) return json({ error: 'upstream_error', status: res.status }, { status: 502 });
  const type = res.headers.get('content-type') || 'application/octet-stream';
  const out = new Response(res.body, {
    status: 200,
    headers: {
      'content-type': type,
      'cache-control': 'public, max-age=3600',
      'access-control-allow-origin': '*',
      'x-proxied-from': target.hostname,
    },
  });
  ctx.waitUntil(cache.put(cacheKey, out.clone()));
  return out;
}

export default {
  /**
   * @param {Request} request
   * @param {{ ASSETS: { fetch: (r: Request) => Promise<Response> } }} env
   * @param {{ waitUntil: (p: Promise<unknown>) => void }} ctx
   */
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.pathname.startsWith('/api/')) {
      if (request.method !== 'GET' && request.method !== 'HEAD') {
        return json({ error: 'method_not_allowed' }, { status: 405, headers: { allow: 'GET, HEAD' } });
      }
      try {
        switch (url.pathname) {
          case '/api/health':
            return health(request);
          case '/api/search/places':
            return await searchPlaces(request, ctx);
          case '/api/fetch':
            return await fetchUpstream(request, ctx);
          case '/api/records':
          case '/api/layers':
          case '/api/sources': {
            const path = { '/api/records': '/data/records.json', '/api/layers': '/data/overlays.json', '/api/sources': '/data/sources.json' }[
              url.pathname
            ];
            const res = await asset(env, path, request);
            if (!res.ok) return json({ error: 'asset_missing', path }, { status: 500 });
            return new Response(res.body, {
              status: 200,
              headers: {
                'content-type': 'application/json; charset=utf-8',
                'cache-control': 'public, max-age=300',
                'access-control-allow-origin': '*',
              },
            });
          }
          default:
            return json({ error: 'not_found', path: url.pathname }, { status: 404 });
        }
      } catch (err) {
        return json({ error: 'worker_error', detail: String(err && err.message) }, { status: 500 });
      }
    }

    // Defensive: if run_worker_first is widened, still behave like a static host.
    if (env && env.ASSETS) return env.ASSETS.fetch(request);
    return new Response('Not found', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8' } });
  },
};

// NOTE: only `default` may be exported from a Workers entrypoint. workerd rejects
// non-function named exports at startup ("Incorrect type for map entry 'VERSION'"
// is the exact failure), so constants stay module-private and are exercised through
// the HTTP surface (see tests/worker.test.mjs → /api/health).

/**
 * Place search (combobox) on top of the Worker-proxied swisstopo SearchServer.
 * Falls back to a local title search when the upstream is unreachable, and
 * always says which one answered.
 */

import { debounce, el, qs, setStatus } from './dom.js';
import { coversPoint, filterRecords, matchesQuery, recordCenter } from './records.js';
import { parsePoint, sanitisePoint } from './store.js';

const MIN_CHARS = 2;
const QUICK = [
  { label: 'Zürich (ZH)', lat: 47.3769, lon: 8.5417, zoom: 12 },
  { label: 'Schweiz', lat: 46.8, lon: 8.23, zoom: 7 },
  { label: 'Basel (BS)', lat: 47.5596, lon: 7.5886, zoom: 12 },
  { label: 'Genf (GE)', lat: 46.2044, lon: 6.1432, zoom: 12 },
];

/**
 * Record-title suggestions used when the swisstopo gazetteer cannot answer
 * (Worker/upstream outage). Pure so it is unit-testable; the coordinates come
 * from `recordCenter`, which falls back to the documented extent — a missing
 * `geo` point must never produce a null map position.
 */
export function fallbackSuggestions(records, query, limit = 6) {
  const hits = (records ?? []).filter((record) => matchesQuery(record, query)).slice(0, limit);
  return hits.map((record) => {
    const center = recordCenter(record);
    return {
      label: record.title.length > 80 ? `${record.title.slice(0, 77)}…` : record.title,
      origin: 'Datensatz',
      lat: center?.lat ?? null,
      lon: center?.lon ?? null,
      bbox: record.extent ?? null,
      recordId: record.id,
    };
  });
}

/**
 * “Search the records too”: the big box is a place search, but a visitor who
 * types a title, a series, a library or a shelfmark expects map results — the
 * OldMapsOnline behaviour. This pure helper turns the query into ONE suggestion
 * that applies the existing keyword filter; the count is what the visitor will
 * actually see, because it runs the same filter pipeline with the current time,
 * provider, type and collection filters. Nothing is invented: zero matches means
 * no suggestion.
 */
export function datasetSuggestion(records, query, state = {}) {
  const text = String(query || '').trim();
  if (text.length < MIN_CHARS) return null;
  const count = filterRecords({ ...state, q: text }, records ?? []).length;
  if (count === 0) return null;
  const label = text.length > 60 ? `${text.slice(0, 57)}…` : text;
  return {
    kind: 'dataset',
    query: text,
    count,
    label: `Karten zum Stichwort „${label}“`,
    origin: count === 1 ? '1 Datensatz' : `${count} Datensätze`,
  };
}

export function init(ctx) {
  const form = qs('#place-search');
  const input = qs('#place-input');
  const submit = qs('#place-submit');
  const list = qs('#place-suggestions');
  const status = qs('#place-status');
  if (!form || !input || !list) return;

  const state = { items: [], active: -1, controller: null, source: null };

  let quickLinks = null;
  // The last place the user chose; when it has a position, offer the point
  // filter (“browse the maps that cover this place”, the OldMapsOnline step).
  let chosenPlace = null;
  const actionWrap = el('div', { class: 'zh-quickranges', id: 'place-action', hidden: true });
  if (status?.after) status.after(actionWrap);
  if (status) {
    const initialAt = parsePoint(ctx.store.getState().at);
    if (initialAt && ctx.store.getState().place) chosenPlace = { label: ctx.store.getState().place, lat: initialAt.lat, lon: initialAt.lon };
  }

  input.value = ctx.store.getState().place || '';
  renderQuickLinks();
  renderPlaceAction();

  /** Records in the current filters whose documented extent covers the place. */
  function countAtPoint(point) {
    if (!point) return 0;
    return filterRecords(ctx.store.getState(), ctx.data.records).filter((record) => coversPoint(record, point.lat, point.lon)).length;
  }

  /** The chip under the search status: one click filters the list to this place. */
  function renderPlaceAction() {
    if (!actionWrap) return;
    const point = chosenPlacePoint();
    if (!point) {
      actionWrap.hidden = true;
      actionWrap.replaceChildren();
      return;
    }
    const active = ctx.store.getState().at === sanitisePoint(`${point.lat},${point.lon}`);
    const count = countAtPoint(point);
    const label = chosenPlace.label.length > 42 ? `${chosenPlace.label.slice(0, 39)}…` : chosenPlace.label;
    const button = el('button', {
      class: 'zh-chip zh-chip--action',
      type: 'button',
      'aria-pressed': active ? 'true' : 'false',
      title: active
        ? 'Punktfilter wieder entfernen; danach gilt wieder der ganze Bestand im Zeitraum.'
        : 'Nur Datensätze zeigen, deren dokumentierter Kartenausschnitt diesen Ort enthält.',
      onclick: () => ctx.store.update({ at: active ? '' : sanitisePoint(`${point.lat},${point.lon}`) }),
    }, [count === 0 ? `Karten an diesem Ort – im Zeitraum keine (${label})` : `Karten an diesem Ort (${count}): ${label}`]);
    actionWrap.replaceChildren(button);
    actionWrap.hidden = false;
  }

  function chosenPlacePoint() {
    if (!chosenPlace) return null;
    if (Number.isFinite(chosenPlace.lat) && Number.isFinite(chosenPlace.lon)) return { lat: chosenPlace.lat, lon: chosenPlace.lon };
    const bbox = chosenPlace.bbox;
    if (bbox && [bbox.west, bbox.east, bbox.south, bbox.north].every(Number.isFinite)) {
      return { lat: (bbox.south + bbox.north) / 2, lon: (bbox.west + bbox.east) / 2 };
    }
    return null;
  }

  function renderQuickLinks() {
    if (!status) return;
    const wrap = el('span', { class: 'zh-quickranges', id: 'place-quick', role: 'group', 'aria-label': 'Schnellauswahl Orte' }, [
      el('span', { class: 'zh-hint', text: 'Schnellauswahl: ' }),
      ...QUICK.map((place) =>
        el('button', {
          class: 'zh-chip',
          type: 'button',
          onclick: () => choose({ ...place, origin: 'Schnellauswahl' }, { zoom: place.zoom }),
        }, [place.label]),
      ),
    ]);
    if (quickLinks?.isConnected) quickLinks.replaceWith(wrap);
    else status.after(wrap);
    quickLinks = wrap;
  }

  function close() {
    list.hidden = true;
    list.replaceChildren();
    state.items = [];
    state.active = -1;
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
  }
  function uniquePlaces(items) {
    const seen = new Set();
    return items.filter((item) => {
      const key = `${String(item.label).toLowerCase()}|${item.lat?.toFixed?.(3) ?? ''}|${item.lon?.toFixed?.(3) ?? ''}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }

  function open(items, source) {
    const unique = uniquePlaces(items);
    state.items = unique;
    state.source = source;
    state.active = unique.length > 0 ? 0 : -1;
    list.replaceChildren(
      ...unique.map((item, index) =>
        el('li', { role: 'none' }, [
          el(
            'button',
            {
              type: 'button',
              role: 'option',
              id: `place-option-${index}`,
              'aria-selected': index === 0 ? 'true' : 'false',
              onclick: () => choose(item),
              onmousemove: () => setActive(index),
            },
            [
              el('span', { text: item.label }),
              el('span', { class: 'zh-suggestions__type', text: item.origin ? item.origin.replace(/^gg25$/, 'swisstopo') : source }),
            ],
          ),
        ]),
      ),
    );
    list.hidden = unique.length === 0;
    input.setAttribute('aria-expanded', unique.length > 0 ? 'true' : 'false');
    updateActive();
  }

  function setActive(index) {
    state.active = index;
    for (const [i, node] of [...list.querySelectorAll('button')].entries()) {
      const selected = i === index;
      node.setAttribute('aria-selected', selected ? 'true' : 'false');
      if (selected) input.setAttribute('aria-activedescendant', node.id);
    }
  }

  function updateActive() {
    if (state.active >= 0) setActive(state.active);
    else input.removeAttribute('aria-activedescendant');
  }

  function choose(place, { zoom } = {}) {
    // “Karten zum Stichwort …”: the search box offers the same keyword filter the
    // sidebar uses. Nothing is opened; the result list and the map follow the
    // store, and the status line states how many rows the filter really leaves.
    if (place?.kind === 'dataset') {
      ctx.store.update({ q: place.query });
      const left = filterRecords({ ...ctx.store.getState(), q: place.query }, ctx.data.records).length;
      setStatus(
        status,
        left === 0
          ? `Kein Datensatz zum Stichwort „${place.query}“ im aktuellen Zeitraum.`
          : `Kartensuche: ${left} Datensätze zum Stichwort „${place.query}“ – die Liste ist entsprechend gefiltert.`,
      );
      input.value = place.query;
      close();
      return;
    }
    const targetZoom = zoom ?? zoomForBbox(place.bbox) ?? 12;
    const hasPoint = Number.isFinite(place.lat) && Number.isFinite(place.lon);
    chosenPlace = { label: place.label, lat: place.lat, lon: place.lon, bbox: place.bbox ?? null };
    renderPlaceAction();
    input.value = place.label;
    if (hasPoint) {
      ctx.store.update({ place: place.label, lat: place.lat, lon: place.lon, zoom: targetZoom });
      ctx.bus.emit('place:selected', { ...place, zoom: targetZoom, source: state.source });
    } else if (place.bbox) {
      // Fallback suggestions come from records; a record without a published
      // point still has a documented extent, so fit that instead of writing a
      // null coordinate into the map state (which used to throw here).
      ctx.store.update({ place: place.label });
      ctx.bus.emit('view:fit', { bounds: place.bbox });
    } else {
      ctx.store.update({ place: place.label });
    }
    // A "Datensatz" suggestion is a record, not a gazetteer place: open it too.
    const record = place.recordId ? ctx.data.recordIndex?.get(place.recordId) : null;
    if (record) {
      ctx.store.update({ selected: record.id });
      ctx.bus.emit('record:selected', { record, source: 'search' });
    }
    setStatus(
      status,
      hasPoint
        ? `Kartenausschnitt auf „${place.label}“ gesetzt (${place.lat.toFixed(4)}, ${place.lon.toFixed(4)}).`
        : place.bbox
          ? `Kartenausschnitt auf „${place.label}“ eingepasst.`
          : `„${place.label}“ ausgewählt.`,
    );
    close();
  }

  function zoomForBbox(bbox) {
    if (!bbox) return null;
    const span = Math.max(bbox.east - bbox.west, bbox.north - bbox.south);
    if (!Number.isFinite(span) || span <= 0) return 14;
    if (span > 20) return 4;
    if (span > 5) return 7;
    if (span > 1) return 9;
    if (span > 0.25) return 11;
    if (span > 0.05) return 13;
    return 15;
  }

  const localFallback = (query) => fallbackSuggestions(ctx.data.records, query);

  /**
   * Netzwerkfehler tragen englische Entwicklertexte ("Failed to fetch"); die
   * Statuszeile nennt nur, was der Besucher wissen muss. Maps-3 hat die gleiche
   * Regel für den Bilddienst in `describeUpstreamError` (iiif.js) — hier bewusst
   * lokal, damit `search.js` keine Abhängigkeit zum Viewer-Modul bekommt.
   */
  function errorReason(err) {
    const message = String(err?.message ?? err ?? '');
    const http = message.match(/\bHTTP (\d{3})\b/);
    if (http) return `HTTP ${http[1]}`;
    if (/failed to fetch|networkerror|network error|load failed|err_/i.test(message)) return 'Netzwerkfehler';
    return message.slice(0, 80) || 'unbekannter Fehler';
  }

  async function suggest(query) {
    state.controller?.abort();
    state.controller = new AbortController();
    setStatus(status, 'Orte werden gesucht …');
    form.setAttribute('aria-busy', 'true');
    // The record search always joins the list (last, so a real place stays the
    // default choice); it is the only suggestion when no place matches.
    const records = datasetSuggestion(ctx.data.records, query, ctx.store.getState());
    try {
      const res = await fetch(`/api/search/places?q=${encodeURIComponent(query)}&limit=8`, { signal: state.controller.signal });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      const items = (data.results ?? []).filter((item) => item.lat !== null && item.lon !== null);
      if (items.length === 0) {
        const local = localFallback(query);
        const combined = records ? [records, ...local] : local;
        open(combined, 'lokal');
        setStatus(status, statusText([], records, local));
        return;
      }
      open(records ? [...items, records] : items, data.source ?? 'swisstopo');
      setStatus(status, statusText(items, records, []));
    } catch (err) {
      if (err?.name === 'AbortError') return;
      const local = localFallback(query);
      const combined = records ? [records, ...local] : local;
      open(combined, 'lokal');
      setStatus(
        status,
        local.length > 0 || records
          ? `Ortssuche nicht erreichbar (${errorReason(err)}) – Vorschläge aus den Datensätzen.`
          : `Ortssuche derzeit nicht erreichbar (${errorReason(err)}).`,
      );
    } finally {
      form.setAttribute('aria-busy', 'false');
    }
  }

  /**
   * One honest sentence about what the list offers: places found, record matches,
   * or neither. Counts come from the suggestions that are really shown.
   */
  function statusText(places, records, local) {
    if (places.length === 0 && !records && local.length === 0) return 'Kein Ort und kein Titeltreffer gefunden.';
    const parts = [];
    if (places.length > 0) parts.push(`${places.length} Ortsvorschläge (swisstopo)`);
    else parts.push('Kein Ortsvorschlag');
    if (records) parts.push(`${records.origin} zu „${records.query}“`);
    else if (local.length > 0) parts.push(`${local.length} Titelvorschläge aus dem Bestand`);
    return `${parts.join(' · ')}. Mit ↓/↑ wählen, Enter bestätigen.`;
  }

  const onInput = debounce(() => {
    const query = input.value.trim();
    if (query.length < MIN_CHARS) {
      close();
      setStatus(status, 'Mindestens zwei Zeichen eingeben – oder eine Schnellauswahl nutzen.');
      return;
    }
    suggest(query);
  }, 260);

  input.addEventListener('input', onInput);
  input.addEventListener('keydown', (event) => {
    if (event.key === 'ArrowDown' && !list.hidden) {
      event.preventDefault();
      setActive(Math.min(state.items.length - 1, state.active + 1));
    } else if (event.key === 'ArrowUp' && !list.hidden) {
      event.preventDefault();
      setActive(Math.max(0, state.active - 1));
    } else if (event.key === 'Home' && !list.hidden) {
      event.preventDefault();
      setActive(0);
    } else if (event.key === 'End' && !list.hidden) {
      event.preventDefault();
      setActive(state.items.length - 1);
    } else if (event.key === 'Enter') {
      if (!list.hidden && state.active >= 0 && state.items[state.active]) {
        event.preventDefault();
        choose(state.items[state.active]);
      } else {
        event.preventDefault();
        onInput.flush();
      }
    } else if (event.key === 'Escape') {
      close();
    }
  });

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    if (!list.hidden && state.items[state.active]) {
      choose(state.items[state.active]);
      return;
    }
    const query = input.value.trim();
    if (query.length >= MIN_CHARS) onInput.flush();
  });

  document.addEventListener('click', (event) => {
    if (!form.contains(event.target)) close();
  });

  submit?.setAttribute('type', 'submit');

  // Keep the field in sync when another module changes the place (e.g. reset),
  // and re-count the “Karten an diesem Ort” chip when the filters change.
  ctx.store.subscribe((next, changed) => {
    if (changed.includes('place') && next.place && next.place !== input.value) input.value = next.place;
    if (changed.some((key) => ['from', 'to', 'q', 'provider', 'type', 'collection', 'at'].includes(key))) renderPlaceAction();
  });

  return { suggest, choose };
}

